local WindUI = loadstring(game:HttpGet("https://github.com/Footagesus/WindUI/releases/latest/download/main.lua"))()
local Junkie = loadstring(game:HttpGet("https://jnkie.com/sdk/library.lua"))()

Junkie.service = "taolao"
Junkie.identifier = "1035567"
Junkie.provider = "12H Checkpoint - Linkvertise"

local is_authenticated = false
if getgenv().SCRIPT_KEY and getgenv().SCRIPT_KEY ~= "" then
    local result = Junkie.check_key(getgenv().SCRIPT_KEY)
    if result and result.valid then
        is_authenticated = true
    end
end

WindUI.Services.junkiedevelopment = {
    Name = "Junkie Development", 
    Icon = "shield-check",
    Args = { "ServiceId", "ApiKey", "Provider" },
    New = function()
    local function Verify(key)
        local result = Junkie.check_key(key)
        if result and result.valid then
            getgenv().SCRIPT_KEY = key
            if writefile then writefile("taolao_key.txt", key) end 
            return true, "Key valid"
        end
        return false, "Invalid key"
    end

        local function Copy()
            local link = Junkie.get_key_link()
            if setclipboard then setclipboard(link) end
            return link
        end
        return { Verify = Verify, Copy = Copy }
    end
}

local windowConfig = {
    Title = "Junkie-Development",
    Theme = "Dark",
    Transparent = true,
    Resizable = true
}

if not is_authenticated then
    windowConfig.KeySystem = {
        Note = "Enter your key to continue.",
        SaveKey = true,
        API = {
            {
                Title = "Junkie",
                Desc  = "Click to copy link",
                Icon  = "key-round",
                Type  = "junkiedevelopment"
            }
        }
    }
end

local Window = WindUI:CreateWindow(windowConfig)

if not is_authenticated then
    repeat task.wait(0.1) until getgenv().SCRIPT_KEY
end

task.wait(3)

Window:Destroy()

